head.script:
scwin.trigger1_onclick = function(e) {
    scwin.$w.executeSubmission("submission1");
};
scwin.__checkErr = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("Unexpected end of JSON input") == -1;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 submission execute 버튼을 클릭한다.
    //1. Click the submission execute button in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 웹스퀘어메뉴 (Ctrl + 마우스오른쪽) 로그보기를 선택한다. 
    //2. Select the Web Square menu (Ctrl + Right Mouse) to view the log.
    //Verify 2. 로그창이 활성화되는데, 에러로그가 발생되지 않는다. (그전버전에서는 그림1처럼 결함로그가 발생됨)
    //2. The log window is activated, but no error log is generated. (In previous versions, a defect log was generated as shown in Figure 1)
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErr()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 12-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
